CREATE TABLE public.assistente_conversas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), titulo text NOT NULL DEFAULT 'Nova consulta', mensagens jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.assistente_conversas TO authenticated; GRANT ALL ON public.assistente_conversas TO service_role; ALTER TABLE public.assistente_conversas ENABLE ROW LEVEL SECURITY; CREATE POLICY conversations_owner ON public.assistente_conversas FOR ALL TO authenticated USING(user_id=auth.uid() AND public.ppm_ativo()) WITH CHECK(user_id=auth.uid() AND public.ppm_ativo());
CREATE FUNCTION public.ppm_proteger_parent() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND auth.uid() IS NOT NULL AND NOT public.ppm_tem_papel('administrador_pmo') THEN IF TG_TABLE_NAME IN ('projeto_elementos','projeto_subelementos','projeto_tarefas') AND (NEW.projeto_id<>OLD.projeto_id OR NEW.responsavel_id IS DISTINCT FROM OLD.responsavel_id) THEN RAISE EXCEPTION 'Somente Administrador/PMO pode mover ou reatribuir itens'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_parent BEFORE UPDATE ON public.projeto_elementos FOR EACH ROW EXECUTE FUNCTION public.ppm_proteger_parent(); CREATE TRIGGER protect_parent BEFORE UPDATE ON public.projeto_subelementos FOR EACH ROW EXECUTE FUNCTION public.ppm_proteger_parent(); CREATE TRIGGER protect_parent BEFORE UPDATE ON public.projeto_tarefas FOR EACH ROW EXECUTE FUNCTION public.ppm_proteger_parent();
CREATE OR REPLACE FUNCTION public.ppm_editar_filho(p uuid,r uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.ppm_pode_ver(p) AND CASE WHEN public.ppm_tem_papel('administrador_pmo') THEN true WHEN public.ppm_tem_papel('auditor') OR public.ppm_tem_papel('alta_administracao') THEN false WHEN public.ppm_tem_papel('tecnico') THEN coalesce(r=auth.uid() AND public.ppm_membro((SELECT area_id FROM public.objetos_acesso WHERE id=p)),false) ELSE public.ppm_pode_editar(p) END $$;
CREATE POLICY ppm_roles_profiles ON public.profiles FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.ppm_papeis WHERE user_id=profiles.id AND public.ppm_tem_papel('auditor')));
CREATE INDEX ON public.assistente_conversas(user_id,updated_at DESC);
ALTER PUBLICATION supabase_realtime ADD TABLE public.assistente_conversas,public.ppm_papeis,public.ppm_usuarios;
REVOKE EXECUTE ON FUNCTION public.ppm_registrar_objeto(),public.ppm_auditar(),public.ppm_carimbar(),public.ppm_validar_filho(),public.ppm_proteger_parent() FROM PUBLIC;